#include "profiles.hpp"
#include "gamer.hpp"
#include <set>
#include <sstream>
#include <stdexcept>
namespace hr {
namespace {void validate(const GameProfile& profile){const std::set<std::string> presets={"competitive","streaming","laptop","quiet","everyday"};if(profile.game.empty()||!presets.count(profile.preset)||profile.retention<1||profile.retention>20)throw std::runtime_error("Invalid game profile");if(profile.enabled&&!profile.backup_folder.empty())validate_backup_folder(wide(profile.backup_folder));}}
GameProfile game_profile(const Store& store,const std::string& game){
    GameProfile profile;profile.game=game;auto key=hex(lower(game));auto data=store.get("game.profile."+key);if(data.empty()){auto old=store.get("session.profile."+key);if(!old.empty()){profile.preset=old;profile.enabled=true;}return profile;}auto rows=decode(data);if(rows.size()!=1||rows[0].size()!=9||rows[0][0]!="2"||lower(rows[0][1])!=lower(game))throw std::runtime_error("Invalid saved game profile; original record preserved");auto& row=rows[0];profile.preset=row[2];profile.power=row[3];if((row[4]!="0"&&row[4]!="1")||(row[8]!="0"&&row[8]!="1"))throw std::runtime_error("Invalid profile flags");profile.animations=row[4]=="1";profile.backup_folder=row[5];size_t used=0;auto retention=std::stoul(row[6],&used);if(retention<1||retention>20)throw std::runtime_error("Invalid backup retention");profile.retention=static_cast<unsigned>(retention);if(used!=row[6].size())throw std::runtime_error("Invalid backup retention");profile.device_profile=row[7];profile.enabled=row[8]=="1";const std::set<std::string> presets={"competitive","streaming","laptop","quiet","everyday"};if(!presets.count(profile.preset)||profile.retention<1||profile.retention>20)throw std::runtime_error("Invalid saved game profile");return profile;
}
SessionSettings profile_settings(const Store& store,const GameProfile& profile){SessionSettings settings;settings.power=profile.power;settings.reduce_animations=profile.animations;if(!profile.device_profile.empty()){auto data=store.get("device.profile."+hex(lower(profile.device_profile)));auto rows=decode(data);if(rows.size()!=1)throw std::runtime_error("Associated monitor/audio profile no longer exists");auto devices=read_device_profile(rows[0]);settings.displays=devices.displays;settings.playback=devices.playback;settings.microphone=devices.microphone;}return settings;}
void save_game_profile(Store& store,const GameProfile& requested){auto profile=requested;auto path=std::filesystem::weakly_canonical(wide(profile.game));if(!path.is_absolute()||(profile.enabled&&!std::filesystem::is_regular_file(path))||lower(utf8(path.extension().wstring()))!=".exe")throw std::runtime_error("Choose an existing game executable");profile.game=utf8(path.wstring());validate(profile);if(profile.enabled&&!profile.power.empty()){auto available=plans();bool exists=false;for(const auto& plan:available)if(plan.guid==profile.power)exists=true;if(!exists)throw std::runtime_error("Selected power plan is unavailable");}if(profile.enabled)profile_settings(store,profile);auto key=hex(lower(profile.game));store.set("game.profile."+key,encode({{"2",profile.game,profile.preset,profile.power,profile.animations?"1":"0",profile.backup_folder,std::to_string(profile.retention),profile.device_profile,profile.enabled?"1":"0"}}));store.set("session.profile."+key,profile.enabled?profile.preset:"");store.save();}
std::string profile_review(const GameProfile& profile){std::ostringstream out;out<<"Game: "<<profile.game<<"\nAutomatic profile: "<<(profile.enabled?"enabled":"disabled")<<"\nPriority preset: "<<profile.preset<<"\nPower plan: "<<(profile.power.empty()?"keep current":profile.power)<<"\nReduce minimize/client/menu animations: "<<(profile.animations?"temporarily":"keep current")<<"\nMonitor/audio profile: "<<(profile.device_profile.empty()?"keep current":profile.device_profile)<<"\nSave folder: "<<(profile.backup_folder.empty()?"automatic backup off":profile.backup_folder)<<"\nRetain "<<profile.retention<<" automatic versions; older automatic versions for this game are removed only after a new successful backup. Manual snapshots are kept.\n\nNovaTune launch completes a save backup before starting the game. Games launched externally are backed up after exit. Completed NovaTune-launched sessions also get an after-exit version. Backup failures are reported. Original settings restore on game exit/NovaTune closure/crash unless changed outside NovaTune. Profiles do not change security settings or promise FPS gains.";return out.str();}
}
